public void LoadFromDisk(string filePath)
{
    if (string.IsNullOrEmpty(filePath) || !File.Exists(filePath)) return;

    var aliasMap = new Dictionary<string, string>(StringComparer.Ordinal)
    {
        ["id"] = "Id",
        ["leaderAccount"] = "LeaderAccountName",
        ["followerAccount"] = "FollowerAccountName",
        ["groupName"] = "GroupName",
        ["isEnabled"] = "IsEnabled",
        ["armedForLive"] = "ArmedForLive",
        ["quantityRatio"] = "QuantityRatio",
        ["fixedLotMode"] = "FixedLotMode",
        ["fixedLotSize"] = "FixedLotSize",
        ["autoSymbolConversion"] = "AutoSymbolConversion",
        ["maxPositionSize"] = "MaxPositionSize",
        ["dailyLossLimit"] = "DailyLossLimit",
        ["isQuarantined"] = "IsQuarantined",
        ["maxSlippageTicks"] = "MaxSlippageTicks",
        ["followerAccounts"] = "FollowerAccounts",
        ["sizingMode"] = "SizingMode",
        ["mode"] = "Mode",
        ["perTickerRatios"] = "PerTickerRatios",
        ["customSymbolMappings"] = "CustomSymbolMappings",
        ["stealthMode"] = "StealthMode"
    };

    var settings = new JsonSerializerSettings
    {
        MissingMemberHandling = MissingMemberHandling.Ignore,
        NullValueHandling = NullValueHandling.Ignore,
        Error = (sender, args) =>
        {
            string member = args.ErrorContext.Member?.ToString();
            object target = args.CurrentObject;
            if (string.IsNullOrEmpty(member) || target == null)
                return;
            var prop = target.GetType().GetProperty(member);
            if (prop == null)
                return;
            Type underlying = System.Nullable.GetUnderlyingType(prop.PropertyType) ?? prop.PropertyType;
            if (underlying.IsEnum)
                args.ErrorContext.Handled = true;
        }
    };

    try
    {
        string json = File.ReadAllText(filePath);
        var jRoot = JObject.Parse(json);

        lock (_lock)
        {
            _relationships.Clear();
            _groups.Clear();

            var relsObj = jRoot["Relationships"] as JObject ?? jRoot["relationships"] as JObject;
            var grpsObj = jRoot["Groups"] as JObject ?? jRoot["groups"] as JObject;
            bool hasStructuredSections = relsObj != null || grpsObj != null;

            if (hasStructuredSections)
            {
                if (relsObj != null)
                {
                    foreach (var kv in relsObj)
                    {
                        if (kv.Value is JObject jObj)
                        {
                            try
                            {
                                var rel = ParseRelationship(jObj, kv.Key);
                                if (rel != null)
                                    _relationships.Add(rel);
                            }
                            catch (Exception ex)
                            {
                                Console.WriteLine($"[LoadFromDisk] Skipping relationship '{kv.Key}': {ex.Message}");
                            }
                        }
                    }
                }

                if (grpsObj != null)
                {
                    foreach (var kv in grpsObj)
                    {
                        if (kv.Value is JObject jObj)
                        {
                            try
                            {
                                var grp = ParseGroup(jObj, kv.Key);
                                if (grp != null)
                                    _groups.Add(grp);
                            }
                            catch (Exception ex)
                            {
                                Console.WriteLine($"[LoadFromDisk] Skipping group '{kv.Key}': {ex.Message}");
                            }
                        }
                    }
                }
            }
            else
            {
                var dict = JsonConvert.DeserializeObject<Dictionary<string, JObject>>(json, settings);
                if (dict != null)
                {
                    foreach (var kv in dict)
                    {
                        if (kv.Value == null)
                            continue;
                        try
                        {
                            var rel = ParseRelationship(kv.Value, kv.Key);
                            if (rel != null)
                                _relationships.Add(rel);
                        }
                        catch (Exception ex)
                        {
                            Console.WriteLine($"[LoadFromDisk] Skipping legacy relationship '{kv.Key}': {ex.Message}");
                        }
                    }
                }
            }
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"[LoadFromDisk EXCEPTION] {ex}");
    }

    JObject NormalizeJObject(JObject source, string fallbackLeader, string fallbackGroupName)
    {
        var normalized = new JObject();

        foreach (var prop in source.Properties())
        {
            if (!aliasMap.ContainsKey(prop.Name))
                normalized[prop.Name] = prop.Value;
        }

        foreach (var prop in source.Properties())
        {
            if (aliasMap.TryGetValue(prop.Name, out string canonical))
            {
                if (normalized[canonical] == null || normalized[canonical].Type == JTokenType.Null)
                    normalized[canonical] = prop.Value;
            }
        }

        var defaults = new JObject
        {
            ["Id"] = Guid.NewGuid().ToString(),
            ["IsEnabled"] = true,
            ["ArmedForLive"] = false,
            ["QuantityRatio"] = 1.0,
            ["FixedLotMode"] = false,
            ["FixedLotSize"] = 1,
            ["AutoSymbolConversion"] = true,
            ["MaxPositionSize"] = 100,
            ["DailyLossLimit"] = 1000.0,
            ["MaxSlippageTicks"] = 0.0,
            ["IsQuarantined"] = false,
            ["PerTickerRatios"] = new JObject(),
            ["CustomSymbolMappings"] = new JObject(),
            ["FollowerAccounts"] = new JArray()
        };

        foreach (var prop in defaults.Properties())
        {
            if (normalized[prop.Name] == null || normalized[prop.Name].Type == JTokenType.Null)
                normalized[prop.Name] = prop.Value;
        }

        if (fallbackLeader != null && (normalized["LeaderAccountName"] == null || normalized["LeaderAccountName"].Type == JTokenType.Null))
            normalized["LeaderAccountName"] = fallbackLeader;
        if (fallbackGroupName != null && (normalized["GroupName"] == null || normalized["GroupName"].Type == JTokenType.Null))
            normalized["GroupName"] = fallbackGroupName;

        return normalized;
    }

    CopierRelationship ParseRelationship(JObject source, string key)
    {
        var normalized = NormalizeJObject(source, fallbackLeader: key, fallbackGroupName: null);
        var rel = JsonConvert.DeserializeObject<CopierRelationship>(normalized.ToString(), settings);
        if (rel == null)
            return null;
        if (string.IsNullOrEmpty(rel.Id))
            rel.Id = Guid.NewGuid().ToString();
        if (string.IsNullOrEmpty(rel.LeaderAccountName))
            rel.LeaderAccountName = key.Contains("_") ? key.Split('_')[0] : key;
        if (string.IsNullOrEmpty(rel.FollowerAccountName))
            rel.FollowerAccountName = key.Contains("_") ? key.Split('_')[1] : "SimCopy2";
        return rel;
    }

    CopierGroup ParseGroup(JObject source, string key)
    {
        var normalized = NormalizeJObject(source, fallbackLeader: null, fallbackGroupName: key);
        var grp = JsonConvert.DeserializeObject<CopierGroup>(normalized.ToString(), settings);
        if (grp == null)
            return null;
        if (string.IsNullOrEmpty(grp.Id))
            grp.Id = Guid.NewGuid().ToString();
        if (string.IsNullOrEmpty(grp.GroupName))
            grp.GroupName = key;
        if (string.IsNullOrEmpty(grp.LeaderAccountName))
            grp.LeaderAccountName = "Sim101";
        if (grp.FollowerAccounts == null)
            grp.FollowerAccounts = new List<string>();
        return grp;
    }
}
